using System.Collections.Generic;
using UnityEngine;

namespace TC2.Game
{
    /// <summary>
    /// The asset kit (D2-026): meshes generated by <c>tc2/art/kit.py</c> in headless Blender and imported from
    /// <c>Resources/TC2Models</c>; a procedural stand-in when a model is missing, so the game always draws something.
    /// </summary>
    public static class Models
    {
        static readonly Dictionary<string, Mesh> Cache = new Dictionary<string, Mesh>();

        public static Mesh Get(string name, System.Func<Mesh> fallback)
        {
            if (Cache.TryGetValue(name, out var m)) return m;
            var go = Resources.Load<GameObject>("TC2Models/" + name);
            var mf = go != null ? go.GetComponentInChildren<MeshFilter>() : null;
            m = mf != null ? mf.sharedMesh : null;
            if (m == null)
            {
                Debug.LogWarning("[TC2] model " + name + " missing: using a stand-in");
                m = fallback();
            }
            Cache[name] = m;
            return m;
        }
    }
}
